<template x-teleport="body">
<div x-show="workflowOpen" x-cloak role="dialog" aria-modal="true" aria-label="Column connections" class="task-workflow-modal fixed inset-0 flex items-center justify-center p-4" style="z-index:90;background:rgba(8,15,30,.55)" @click.self="workflowOpen=false" @keydown.escape.window="workflowOpen=false">
<section class="rounded-2xl border p-5 w-full max-w-3xl overflow-y-auto" style="max-height:85vh;background:var(--bg-card);color:var(--text-primary);border-color:var(--border-soft)">
<div class="flex justify-between gap-3"><h2 class="text-lg font-bold">Column connections</h2><button type="button" class="task-modal-close" @click="workflowOpen=false" aria-label="Close connections">✕</button></div>
<p class="text-sm my-3" style="color:var(--text-muted)">Choose where tasks go when a stage is completed or a card is dragged. Rules are checked from top to bottom.</p>
<p class="text-sm p-4 rounded-xl" style="background:var(--bg-glass-input);color:var(--text-muted)" x-show="!workflowRules.length">No routes yet. Completed tasks move to Done, and cards can be dragged to any column.</p>
<template x-for="(rule,index) in workflowRules" :key="index"><div class="border rounded-xl p-3 my-2" style="border-color:var(--border-soft)"><div class="task-workflow-fields">
<label class="text-xs">When<select class="theme-input" x-model="rule.trigger"><option value="completed">Stage completed</option><option value="manual">Manual drop</option></select></label>
<label class="text-xs">Condition<select class="theme-input" x-model="rule.condition"><option value="always">Always</option><option value="priority">Priority matches</option><option value="label">Category matches</option></select></label>
<label class="text-xs" x-show="rule.condition==='priority'">Priority<select class="theme-input" x-model="rule.value"><option value="">Choose</option>@foreach($priorities as $key=>$p)<option value="{{ $key }}">{{ $p['label'] }}</option>@endforeach</select></label>
<label class="text-xs" x-show="rule.condition==='label'">Category<select class="theme-input" x-model="rule.value"><option value="">Choose</option><template x-for="label in boardLabels" :key="label.id"><option :value="String(label.id)" x-text="label.name"></option></template></select></label>
<label class="text-xs">Destination<select class="theme-input" x-model.number="rule.target_column_id"><option value="">Choose column</option><template x-for="col in workflowColumns.filter(c=>c.id!==workflowColumn)" :key="col.id"><option :value="col.id" x-text="col.name"></option></template></select></label></div>
<div class="flex gap-3 mt-2"><button class="form-chip" type="button" @click="if(index>0){const r=workflowRules.splice(index,1)[0];workflowRules.splice(index-1,0,r)}">Move up</button><button class="form-chip" type="button" @click="workflowRules.splice(index,1)">Remove route</button></div></div></template>
<div class="task-workflow-footer"><button class="form-chip" type="button" @click="workflowRules.push({trigger:'completed',condition:'always',value:'',target_column_id:''})">Add route</button>
<button class="form-chip task-modal-primary" type="button" @click="saveWorkflow()">Save connections</button></div><p class="text-sm mt-2" role="alert" x-text="notice"></p>
<details class="text-xs mt-3" style="color:var(--text-muted)"><summary>How routes work</summary><p class="mt-2">Completion moves one stage using the first matching rule. A work column starts the next stage at 0%; Done finishes the task at 100%. Manual drops are unrestricted until you add manual rules.</p></details>
</section></div></template>
